def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u, v, w, i + 1))
        adj[u].append((v, w, i + 1))
        adj[v].append((u, w, i + 1))

    start = int(lines[1 + m])

    # Dijkstra's algorithm to find shortest distances
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w, eid in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Build shortest-path tree with minimum total edge weight
    # For each vertex v != start, choose one parent edge on a shortest path
    # that minimizes the edge weight

    total_weight = 0
    edge_indices = []

    for v in range(1, n + 1):
        if v == start:
            continue

        min_w = float('inf')
        best_edge_id = -1

        # Check all edges incident to v
        for u, w, eid in adj[v]:
            # Edge (u, v) is on a shortest path if dist[u] + w == dist[v]
            if dist[u] + w == dist[v]:
                if w < min_w:
                    min_w = w
                    best_edge_id = eid

        if best_edge_id != -1:
            total_weight += min_w
            edge_indices.append(best_edge_id)

    edge_indices.sort()

    return f"{total_weight}\n{' '.join(map(str, edge_indices))} "
