            row_constraints[u].add(v)
        elif (s1_type == 'T' and s2_type == 'B') or (s1_type == 'B' and s2_type == 'T'):
            u, v = (s1_idx, s2_idx) if s1_type == 'T' else (s2_idx, s1_idx)
            col_constraints[u].add(v)

