        adj = defaultdict(list)
        for node, neighbors in constraints.items():
            adj[node] = list(neighbors)

        WHITE, GRAY, BLACK = 0, 1, 2
        color = {}

        for start in range(n):
            if start in adj:
                if DFS(start, adj, color, WHITE):
                    return True

        def DFS(node, adj, color, prev_color):
            color[node] = GRAY
            for neighbor in adj[node]:
                if neighbor not in color:
                    color[neighbor] = WHITE
                if color[neighbor] == GRAY:
                    return True
                if DFS(neighbor, adj, color, color[node]):
                    return True
            color[node] = BLACK
            return False

        return False

    if has_cycle(row_constraints, n) or has_cycle(col_constraints, m):
        return "No solution\n"

    # Build permutations using topological sort
    def topo_sort(constraints, n):
        adj = defaultdict(list)
        in_degree = defaultdict(int)
        for node in range(n):
            adj[node] = []
            in_degree[node] = 0

        for node, neighbors in constraints.items():
            for neighbor in neighbors:
                adj[node].append(neighbor)
                in_degree[neighbor] += 1

        queue = deque([i for i in range(n) if in_degree[i] == 0])
        result = []
        while queue:
            node = queue.popleft()
            result.append(node)
            for neighbor in adj[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # Convert 0-indexed to 1-indexed and return as space-separated string
        return ' '.join(str(x + 1) for x in result)

    row_perm = topo_sort(row_constraints, n)
    col_perm = topo_sort(col_constraints, m)

    return f"{row_perm}\n{col_perm}\n"


