    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = list(map(int, lines[i].split()))
        u, v = parts[0], parts[1]
        adj[u].append(v)
        adj[v].append(u)

    min_path_len = (n + k - 1) // k  # ceil(n/k)

    # Try to find a path first
    def find_path():
        for start in range(1, n + 1):
            stack = [(start, [start])]
            while stack:
                u, path = stack.pop()
                if len(path) >= min_path_len:
                    return path
                for v in adj[u]:
                    if v not in path:
                        stack.append((v, path + [v]))
        return None

    path = find_path()
    if path:
        result = ["PATH", str(len(path)), " ".join(map(str, path))]
        return "\n".join(result)

    # Find k valid cycles
    cycles = []

    def find_cycles_from(start):
        visited = {start}
        stack = [(start, [start])]
        while stack:
            u, path = stack.pop()
            for v in adj[u]:
                if v in path:
                    if len(path) >= 3:
                        cycles.append(path + [v])
                elif v not in visited:
                    visited.add(v)
                    stack.append((v, path + [v]))

    found_cycles = False
    for start in range(1, n + 1):
        if not found_cycles:
            find_cycles_from(start)
        if len(cycles) >= k:
            found_cycles = True
            break

    # Filter cycles: length >= 3 and not divisible by 3
    valid_cycles = [c for c in cycles if len(c) % 3 != 0 and len(c) >= 3][:k]

    if len(valid_cycles) >= k and k > 0:
        result = ["CYCLES"]
        for c in valid_cycles:
            result.append(str(len(c)))
            result.append(" ".join(map(str, c)))
        return "\n".join(result)

    return "-1"
