    n, m = map(int, lines[0].split())
    adj = [[] for _ in range(n)]

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u-1].append(v-1)

    d = [[-1] * n for _ in range(n)]

    # BFS from each node for all-pairs shortest paths
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        for i in range(n):
            d[start][i] = dist[i]

    best = -1
    best_tuple = None

    # Find 4 distinct cities maximizing sum of paths
    for i in range(n):
        for j in range(n):
            if i == j or d[i][j] == -1:
                continue
            for k in range(n):
                if k == i or k == j or d[j][k] == -1:
                    continue
                for l in range(n):
                    if l == i or l == j or l == k or d[k][l] == -1:
                        continue

                    total = d[i][j] + d[j][k] + d[k][l]
                    if total > best:
                        best = total
                        best_tuple = (i + 1, j + 1, k + 1, l + 1)

    return ' '.join(map(str, best_tuple))

