# Your solution code here
def solution(input_str):
    input_lines = input_str.strip().split('\n')
    n, m = int(input_lines[0]), int(input_lines[1])

    d = list(map(int, input_lines[2].split()))
    h = list(map(int, input_lines[3].split()))

    # Precompute prefix sums for distance calculation
    prefix_dist = [0] * (n + 1)
    for i in range(n):
        prefix_dist[i+1] = prefix_dist[i] + d[i]

    total_dist = prefix_dist[n]

    def dist_clockwise(i, j):
        """Clockwise distance from tree i to tree j (0-indexed)"""
        if i == j:
            return 0
        return prefix_dist[j+1] - prefix_dist[i]

    def get_dist(i, j):
        """Actual shortest path distance between trees i and j (not through children)"""
        if i == j:
            return 0
        cw = dist_clockwise(i, j)
        ccw = total_dist - cw
        return min(cw, ccw)

    # Segment tree to find max height in any range
    size = 1
    while size <= n:
        size *= 2

    tree = [(0, -1)] * (2 * size)  # (max_height, index)

    for i in range(n):
        tree[size + i] = (h[i], i)

    for i in range(size - 1, 0, -1):
        left_val = tree[2*i]
        right_val = tree[2*i+1]
        if left_val[0] >= right_val[0]:
            tree[i] = left_val
        else:
            tree[i] = right_val

    def query_max(l, r):  # inclusive [l, r]
        """Return (max_height, index) or (0, -1) if range is invalid"""
        if l > r or l >= n or r < 0:
            return (0, -1)
        l0, r0 = l + size, r + size
        best = (0, -1)
        while l0 <= r0:
            if l0 % 2 == 1:
                if tree[l0][0] >= best[0]:
                    best = tree[l0]
                l0 += 1
            if r0 % 2 == 0:
                if tree[r0][0] >= best[0]:
                    best = tree[r0]
                r0 -= 1
            l0 //= 2
            r0 //= 2
        return best

    results = []

    for i in range(m):
        a, b = map(int, input_lines[4 + i].split())
        l_excl, r_excl = a - 1, b - 1

        # Valid indices (0-indexed)
        if l_excl < r_excl:
            # Exclude [l_excl, r_excl]
            valid1 = list(range(0, l_excl)) if l_excl > 0 else []
            valid2 = list(range(r_excl + 1, n)) if r_excl < n - 1 else []
            valid = valid1 + valid2
        else:
            # Exclude [l_excl, n-1] ∪ [0, r_excl]
            valid = list(range(r_excl + 1, l_excl)) if l_excl - 1 > r_excl else []

        if len(valid) < 2:
            results.append(0)
            continue

        # Get top 3 indices by height for efficiency
        sorted_indices = sorted(valid, key=lambda x: -h[x])[:3]

        if len(sorted_indices) < 2:
            results.append(0)
            continue

        max_energy = 0
        for i_idx in range(len(sorted_indices)):
            for j_idx in range(i_idx + 1, len(sorted_indices)):
                u, v = sorted_indices[i_idx], sorted_indices[j_idx]
                energy = 2 * h[u] + 2 * h[v] + get_dist(u, v)
                if energy > max_energy:
                    max_energy = energy

        results.append(str(max_energy))

    return '\n'.join(results)
