            paths = []
            stack = [(0, 0, [])]
            while stack:
                r, c, seq = stack.pop()
                full_seq = seq + [grid[r][c]]
                if r == n - 1 and c == m - 1:
                    paths.append(''.join(full_seq))
                else:
                    if c + 1 < m:
                        stack.append((r, c + 1, seq))
                    if r + 1 < n:
                        stack.append((r + 1, c, seq))
            return paths

        paths = find_all_paths()
        if not paths:
            return False

        for path in paths:
            balance = 0
            for ch in path:
                balance += 1 if ch == '(' else -1
                if balance < 0 or balance > len(path):
                    return False
            if balance != 0:
                return False
        return True

